<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?php $editId=(int)session()->getFlashdata('edit_user_id'); ?><?= view('partials/breadcrumbs',['title'=>'Users','subtitle'=>'Create and maintain Admin, Barangay Official, and Borrower accounts.']) ?><div class="grid-2 uneven"><section class="panel"><div class="table-wrap" role="region" aria-label="User accounts table" tabindex="0"><table><thead><tr><th>User</th><th>Role</th><th>Contact</th><th>Status</th><th class="actions-head">Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><b><?= esc($u['display_name']) ?></b><small>@<?= esc($u['username']) ?></small></td><td><?= esc(role_label($u['role'])) ?></td><td><?= esc($u['email']?:'—') ?><small><?= esc($u['contact_number']?:'') ?></small></td><td><?= view('partials/status_badge',['status'=>$u['status']]) ?></td><td class="actions"><button class="btn small ghost" type="button" data-dialog-open="user-<?= (int)$u['id'] ?>">Edit</button><?php if((int)$u['id']!==current_user_id()): ?><form method="post" action="<?= site_url('users/'.$u['id'].'/status') ?>" data-confirm="<?= esc(($u['status']==='active'?'Deactivate user ':'Activate user ').$u['display_name'].'?'.($u['status']==='active'?' They will be blocked from signing in immediately.':''), 'attr') ?>"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $u['status']==='active'?'inactive':'active' ?>"><button class="btn small" type="submit"><?= $u['status']==='active'?'Deactivate':'Activate' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(empty($users)): ?><tr><td colspan="5"><div class="empty">No user accounts found.</div></td></tr><?php endif; ?></tbody></table></div></section><?php foreach($users as $u): ?><?php $editing=$editId===(int)$u['id']; ?><dialog class="form-dialog" id="user-<?= (int)$u['id'] ?>" <?= $editing?'data-dialog-auto-open':'' ?>><div class="dialog-head"><h2>Edit <?= esc($u['display_name']) ?></h2><button type="button" data-dialog-close aria-label="Close"><?= ui_icon('x') ?></button></div><form method="post" action="<?= site_url('users/'.$u['id']) ?>" class="stack-form"><?= csrf_field() ?><label>Display Name<input name="display_name" value="<?= esc($editing?old('display_name',$u['display_name']):$u['display_name']) ?>" required<?= $editing?form_invalid('display_name'):'' ?>><?= $editing?form_error('display_name'):'' ?></label><label>Email<input type="email" name="email" value="<?= esc($editing?old('email',$u['email']??''):$u['email']??'') ?>"<?= $editing?form_invalid('email'):'' ?>><?= $editing?form_error('email'):'' ?></label><label>Contact Number<input name="contact_number" value="<?= esc($editing?old('contact_number',$u['contact_number']??''):$u['contact_number']??'') ?>"<?= $editing?form_invalid('contact_number'):'' ?>><?= $editing?form_error('contact_number'):'' ?></label><label>Address<textarea name="address" rows="2"<?= $editing?form_invalid('address'):'' ?>><?= esc($editing?old('address',$u['address']??''):$u['address']??'') ?></textarea><?= $editing?form_error('address'):'' ?></label><label>Role<select name="role"<?= $editing?form_invalid('role'):'' ?>><?php foreach(config('BantayGamit')->roles as $k=>$v): ?><option value="<?= esc($k) ?>" <?= ($editing?old('role',$u['role']):$u['role'])===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select><?= $editing?form_error('role'):'' ?></label><label>Status<select name="status"<?= $editing?form_invalid('status'):'' ?>><option value="active" <?= ($editing?old('status',$u['status']):$u['status'])==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= ($editing?old('status',$u['status']):$u['status'])==='inactive'?'selected':'' ?>>Inactive</option></select><?= $editing?form_error('status'):'' ?></label><label>New Password <small>Leave blank to keep current password</small><span class="password-field"><input id="user-password-<?= (int)$u['id'] ?>" type="password" name="password" minlength="8" autocomplete="new-password"<?= $editing?form_invalid('password'):'' ?>><button type="button" data-password-toggle="user-password-<?= (int)$u['id'] ?>" aria-label="Show password" aria-pressed="false" title="Show password"><?= ui_icon('eye') ?></button></span><?= $editing?form_error('password'):'' ?></label><div class="form-actions"><button class="btn" type="button" data-dialog-close>Cancel</button><button class="btn primary" type="submit">Save Changes</button></div></form></dialog><?php endforeach; ?><aside class="panel action-panel"><h2>Create Account</h2><form method="post" action="<?= site_url('users') ?>" class="stack-form"><?= csrf_field() ?><label>Username<input name="username" required value="<?= esc($editId?'':old('username')) ?>"<?= !$editId?form_invalid('username'):'' ?>><?= !$editId?form_error('username'):'' ?></label><label>Display Name<input name="display_name" required value="<?= esc($editId?'':old('display_name')) ?>"<?= !$editId?form_invalid('display_name'):'' ?>><?= !$editId?form_error('display_name'):'' ?></label><label>Email<input type="email" name="email" value="<?= esc($editId?'':old('email')) ?>"<?= !$editId?form_invalid('email'):'' ?>><?= !$editId?form_error('email'):'' ?></label><label>Contact Number<input name="contact_number" value="<?= esc($editId?'':old('contact_number')) ?>"<?= !$editId?form_invalid('contact_number'):'' ?>><?= !$editId?form_error('contact_number'):'' ?></label><label>Address<textarea name="address" rows="2"<?= !$editId?form_invalid('address'):'' ?>><?= esc($editId?'':old('address')) ?></textarea><?= !$editId?form_error('address'):'' ?></label><label>Role<select name="role"<?= !$editId?form_invalid('role'):'' ?>><?php foreach(config('BantayGamit')->roles as $k=>$v): ?><option value="<?= esc($k) ?>" <?= (!$editId?old('role','borrower'):'borrower')===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select><?= !$editId?form_error('role'):'' ?></label><label>Temporary Password<span class="password-field"><input id="create-user-